lemma ulmSubgroup_add_nat (α : Ordinal) (n : ℕ) :
    ulmSubgroup p (α + n) (G := G) =
      { x | ∃ y ∈ ulmSubgroup p α (G := G), p ^ n • y = x }

lemma add_zsmul_mem_iff_of_mem {β : Ordinal.{0}} {x c : G}
    (hx : x ∈ ulmSubgroup p β (G := G)) (n : ℤ) :
    c + n • x ∈ ulmSubgroup p β (G := G) ↔ c ∈ ulmSubgroup p β (G := G)

lemma mem_ulmSubgroup_zsmul_iff_of_pSocle [Fact p.Prime] {g : G}
    (hpg : p • g = 0) {n : ℤ} (hn : ¬ (p : ℤ) ∣ n) (β : Ordinal) :
    n • g ∈ ulmSubgroup p β (G := G) ↔ g ∈ ulmSubgroup p β (G := G)

lemma IsPure.range_of_heightPresOn [Fact p.Prime] {A : AddSubgroup G} {B : AddSubgroup H}
    (hA : IsPure p A) (φ : A →+ B) (hφ : IsHeightPresOn p φ) :
    IsPure p ((⊤ : AddSubgroup A).map (B.subtype.comp φ))
